import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan } from "../lib/plans";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  const d = typeof date === "string" ? new Date(date) : date;
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function formatNumber(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}K`;
  return String(n);
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);

  const [
    chartCount,
    activeChartCount,
    draftChartCount,
    totalViews,
    totalRecommendations,
    subscription,
    recentCharts,
    widgetConfig,
    recommenderConfig,
    assignmentCount,
    recentEventCount,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.sizeChart.count({ where: { shop, status: "active" } }),
    db.sizeChart.count({ where: { shop, status: "draft" } }),
    db.analyticsEvent.count({ where: { shop, eventType: "view" } }),
    db.analyticsEvent.count({ where: { shop, eventType: "recommend" } }),
    db.subscription.findUnique({ where: { shop } }),
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      take: 5,
      select: {
        id: true,
        name: true,
        category: true,
        status: true,
        updatedAt: true,
      },
    }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.chartAssignment.count({ where: { shop } }),
    db.analyticsEvent.count({
      where: { shop, createdAt: { gte: sevenDaysAgo } },
    }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  // Onboarding steps
  const hasChart = chartCount > 0;
  const hasAssignment = assignmentCount > 0;
  const hasWidget = widgetConfig !== null;
  const hasRecommender =
    recommenderConfig !== null && recommenderConfig.enabled;
  const canUseAi = plan.limits.aiRecommender;

  // Steps: install (always done), chart, assignment, widget, ai (only if eligible)
  const onboardingSteps: Array<{ label: string; done: boolean }> = [
    { label: "Install app", done: true },
    { label: "Create first size chart", done: hasChart },
    { label: "Assign chart to products", done: hasAssignment },
    { label: "Customize widget", done: hasWidget },
    ...(canUseAi
      ? [{ label: "Enable AI recommender", done: hasRecommender }]
      : []),
  ];
  const completedSteps = onboardingSteps.filter((s) => s.done).length;
  const totalSteps = onboardingSteps.length;

  // Chart limit usage for free plan
  const chartLimit = plan.limits.maxCharts;
  const chartsUsedPercent =
    chartLimit > 0 ? Math.min(100, Math.round((chartCount / chartLimit) * 100)) : 0;

  const recentChartsFormatted = recentCharts.map((c) => ({
    ...c,
    updatedAt: c.updatedAt.toISOString(),
  }));

  return {
    shop,
    chartCount,
    activeChartCount,
    draftChartCount,
    totalViews,
    totalRecommendations,
    recentEventCount,
    plan,
    recentCharts: recentChartsFormatted,
    onboardingSteps,
    completedSteps,
    totalSteps,
    chartLimit,
    chartsUsedPercent,
    isNewUser: chartCount === 0,
  };
};

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function Dashboard() {
  const {
    chartCount,
    activeChartCount,
    draftChartCount,
    totalViews,
    totalRecommendations,
    recentEventCount,
    plan,
    recentCharts,
    onboardingSteps,
    completedSteps,
    totalSteps,
    chartLimit,
    chartsUsedPercent,
    isNewUser,
  } = useLoaderData<typeof loader>();

  const isFreePlan = plan.id === "free";
  const isOnboardingComplete = completedSteps === totalSteps;
  const progressPercent = Math.round((completedSteps / totalSteps) * 100);

  return (
    <s-page heading="Dashboard">

      {/* ------------------------------------------------------------------ */}
      {/* Welcome Banner — new users only                                     */}
      {/* ------------------------------------------------------------------ */}
      {isNewUser && (
        <s-section>
          <s-banner tone="info">
            <s-stack direction="block" gap="base">
              <s-heading>Welcome to Size Chart & Recommender</s-heading>
              <s-paragraph>
                Reduce size-related returns by up to 40% with beautiful size
                charts and AI-powered recommendations. You're just a few steps
                away from your first published chart.
              </s-paragraph>
              <s-stack direction="inline" gap="base">
                <s-button href="/app/size-charts" variant="primary">
                  Create your first chart
                </s-button>
                <s-button href="/app/pricing">View plans</s-button>
              </s-stack>
            </s-stack>
          </s-banner>
        </s-section>
      )}

      {/* ------------------------------------------------------------------ */}
      {/* Metrics Row — 4 cards                                               */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Overview">
        <s-stack direction="inline" gap="base">

          {/* Size Charts */}
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{formatNumber(chartCount)}</s-heading>
              <s-text>Size Charts</s-text>
              <s-text tone="neutral">
                {activeChartCount} active · {draftChartCount} draft
              </s-text>
            </s-stack>
          </s-box>

          {/* Chart Views */}
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{formatNumber(totalViews)}</s-heading>
              <s-text>Chart Views</s-text>
              <s-text tone="neutral">
                {recentEventCount} events in last 7 days
              </s-text>
            </s-stack>
          </s-box>

          {/* AI Recommendations */}
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{formatNumber(totalRecommendations)}</s-heading>
              <s-text>AI Recommendations</s-text>
              <s-text tone="neutral">
                {plan.limits.aiRecommender
                  ? "Recommender enabled"
                  : "Upgrade to unlock"}
              </s-text>
            </s-stack>
          </s-box>

          {/* Current Plan */}
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>{plan.name}</s-heading>
              <s-text>Current Plan</s-text>
              <s-text tone="neutral">
                {plan.price === 0 ? "Free forever" : `$${plan.price}/month`}
              </s-text>
              {isFreePlan && (
                <s-button href="/app/pricing" variant="primary">
                  Upgrade
                </s-button>
              )}
            </s-stack>
          </s-box>

        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Onboarding Checklist                                                */}
      {/* ------------------------------------------------------------------ */}
      {!isOnboardingComplete && (
        <s-section heading="Getting Started">
          <s-stack direction="block" gap="base">
            <s-stack direction="block" gap="small-200">
              <s-text>
                {completedSteps} of {totalSteps} steps completed
              </s-text>
              <s-progress-bar
                progress={progressPercent}
                tone="success"
              />
            </s-stack>

            <s-stack direction="block" gap="small-200">
              {onboardingSteps.map((step) => (
                <s-box
                  key={step.label}
                  padding="base"
                  borderWidth="base"
                  borderRadius="base"
                  background={step.done ? "subdued" : undefined}
                >
                  <s-stack direction="inline" gap="base">
                    <s-badge tone={step.done ? "success" : "neutral"}>
                      {step.done ? "Done" : "To do"}
                    </s-badge>
                    <s-text tone={step.done ? "neutral" : undefined}>
                      {step.label}
                    </s-text>
                  </s-stack>
                </s-box>
              ))}
            </s-stack>
          </s-stack>
        </s-section>
      )}

      {/* ------------------------------------------------------------------ */}
      {/* Quick Actions                                                        */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Quick Actions">
        <s-stack direction="inline" gap="base">

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              <s-stack direction="block" gap="small-100">
                <s-text>Create Size Chart</s-text>
                <s-text tone="neutral">
                  Build from a template or start blank. Takes under 3 minutes.
                </s-text>
              </s-stack>
              <s-button href="/app/size-charts" variant="primary">
                Create Chart
              </s-button>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              <s-stack direction="block" gap="small-100">
                <s-text>Customize Widget</s-text>
                <s-text tone="neutral">
                  Control how your size chart appears in the storefront.
                </s-text>
              </s-stack>
              <s-button href="/app/widget">Customize</s-button>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              <s-stack direction="block" gap="small-100">
                <s-text>View Analytics</s-text>
                <s-text tone="neutral">
                  Track chart views, recommendations, and conversions.
                </s-text>
              </s-stack>
              <s-button href="/app/analytics">
                {plan.limits.analytics ? "View Analytics" : "Upgrade to Unlock"}
              </s-button>
            </s-stack>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="base">
              <s-stack direction="block" gap="small-100">
                <s-text>Configure AI Recommender</s-text>
                <s-text tone="neutral">
                  Let shoppers find their size from height, weight, and body
                  type.
                </s-text>
              </s-stack>
              <s-button href="/app/recommender">
                {plan.limits.aiRecommender ? "Configure AI" : "Upgrade to Unlock"}
              </s-button>
            </s-stack>
          </s-box>

        </s-stack>
      </s-section>

      {/* ------------------------------------------------------------------ */}
      {/* Recent Charts                                                        */}
      {/* ------------------------------------------------------------------ */}
      <s-section heading="Recent Size Charts">
        {recentCharts.length === 0 ? (
          <s-box padding="large-200">
            <s-stack direction="block" gap="base">
              <s-heading>No size charts yet</s-heading>
              <s-paragraph>
                Create your first size chart to help customers find their
                perfect fit and reduce size-related returns by up to 40%.
              </s-paragraph>
              <s-button href="/app/size-charts" variant="primary">
                Create your first chart
              </s-button>
            </s-stack>
          </s-box>
        ) : (
          <s-stack direction="block" gap="small-200">
            {recentCharts.map((chart) => (
              <s-box
                key={chart.id}
                padding="base"
                borderWidth="base"
                borderRadius="base"
              >
                <s-stack direction="inline" gap="base">
                  <s-stack direction="block" gap="small-100">
                    <s-text>{chart.name}</s-text>
                    <s-stack direction="inline" gap="small-100">
                      <s-badge tone="neutral">{chart.category}</s-badge>
                      <s-badge
                        tone={chart.status === "active" ? "success" : "neutral"}
                      >
                        {chart.status === "active" ? "Active" : "Draft"}
                      </s-badge>
                      <s-text tone="neutral">
                        Updated {formatDate(chart.updatedAt)}
                      </s-text>
                    </s-stack>
                  </s-stack>
                  <s-link href={`/app/size-charts/${chart.id}`}>Edit</s-link>
                </s-stack>
              </s-box>
            ))}
            <s-link href="/app/size-charts">View all charts</s-link>
          </s-stack>
        )}
      </s-section>

      {/* ================================================================== */}
      {/* ASIDE — Plan Details                                                */}
      {/* ================================================================== */}
      <s-section slot="aside" heading="Plan Details">
        <s-stack direction="block" gap="base">
          <s-stack direction="block" gap="small-100">
            <s-badge tone={isFreePlan ? "neutral" : "success"}>
              {plan.name} Plan
            </s-badge>
            <s-text tone="neutral">
              {plan.price === 0 ? "Free forever" : `$${plan.price}/month`}
            </s-text>
          </s-stack>

          {isFreePlan && chartLimit > 0 && (
            <s-stack direction="block" gap="small-200">
              <s-text>
                {chartCount} / {chartLimit} charts used
              </s-text>
              <s-progress-bar
                progress={chartsUsedPercent}
                tone={chartsUsedPercent >= 80 ? "caution" : "success"}
              />
              {chartsUsedPercent >= 80 && (
                <s-text tone="caution">
                  Almost at your chart limit. Upgrade for unlimited charts.
                </s-text>
              )}
            </s-stack>
          )}

          <s-unordered-list>
            {plan.features.map((feature, i) => (
              <s-list-item key={i}>{feature}</s-list-item>
            ))}
          </s-unordered-list>

          {isFreePlan ? (
            <s-button href="/app/pricing" variant="primary">
              Upgrade Plan
            </s-button>
          ) : (
            <s-button href="/app/pricing">Manage Plan</s-button>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================== */}
      {/* ASIDE — Getting Started Links                                       */}
      {/* ================================================================== */}
      <s-section slot="aside" heading="Getting Started">
        <s-unordered-list>
          <s-list-item>
            <s-link href="/app/size-charts">
              Create a chart from templates
            </s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/widget">Customize widget appearance</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/recommender">
              Enable AI size recommendations
            </s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/pricing">View plans &amp; features</s-link>
          </s-list-item>
        </s-unordered-list>
      </s-section>

      {/* ================================================================== */}
      {/* ASIDE — Need Help?                                                  */}
      {/* ================================================================== */}
      <s-section slot="aside" heading="Need Help?">
        <s-stack direction="block" gap="small-200">
          <s-text tone="neutral">
            Our team is here to help you get the most from Size Chart &amp;
            Recommender.
          </s-text>
          <s-unordered-list>
            <s-list-item>
              <s-link href="mailto:support@sizechart.app">
                Email support
              </s-link>
            </s-list-item>
            <s-list-item>
              <s-link href="/app/settings">App settings</s-link>
            </s-list-item>
          </s-unordered-list>
          {plan.limits.prioritySupport && (
            <s-badge tone="success">Priority support active</s-badge>
          )}
        </s-stack>
      </s-section>

    </s-page>
  );
}

